baseline_plantuml:
@startuml
' Define classes and their attributes
class Driver {
  - id: String (unique)
  - name: String
  - isSick: boolean
}

class Bus {
  - licensePlate: String (max 10)
  - isInRepair: boolean
}

class Route {
  - routeNumber: Integer (max 9999)
}

class Assignment {
  - date: Date
}

class Shift {
  - shiftType: ShiftType
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

' Define relationships
Driver --> Shift : assigned to
Bus --> Assignment : assigned to
Route --> Assignment : assigned to
Assignment "1" --> "3" Shift : has
Shift "1" --> "1" Assignment : belongs to
Shift --> Driver : assigned to
Shift --> ShiftType : uses

' Notes for constraints
note right of Assignment
  Each Assignment represents a Bus assigned to a Route on a specific Date.
  A Bus can serve at most one Route per day.
  A Route can have multiple Buses assigned per day.
end note

note right of Shift
  Each Assignment has exactly three Shifts (Morning, Afternoon, Night).
  A Shift must be assigned a Driver.
  A Driver can be assigned to multiple Shifts per day.
end note

@enduml

