taxonomy_plantuml:
@startuml
abstract class Sensor {
  - vendorId: String
  - description: String
  - unit: String
  - room: Room
  - measuredValues: List<MeasuredValue>
  - lastValue: MeasuredValue
}

class SensorController {
  - sensors: List<Sensor>
  - apartment: Apartment
  - inhabitants: List<Inhabitant>
}

class Apartment {
  - address: String
  - email: String
  - sensorController: SensorController
  - rooms: List<Room>
  - inhabitants: List<Inhabitant>
}

class Room {
  - description: String
  - sensors: List<Sensor>
}

class Inhabitant {
  - username: String
  - password: String
  - hasAdminRights: Boolean
  - apartment: Apartment
  - thresholds: List<Threshold>
  - sensors: List<Sensor>  // Admin-only
}

class Threshold {
  - value: Float
  - sensor: Sensor
  - inhabitant: Inhabitant
}

class MeasuredValue {
  - timestamp: DateTime
  - value: Float
  - sensor: Sensor
}

class TemperatureSensor {
  - min: Float
  - max: Float
}

class PowerSensor {
  - counter: Float
}

class "E-Monitor" {
  - sensorController: SensorController
}

SensorController "1" *-- "1..*" Sensor : manages
SensorController "1" *-- "1" Apartment : manages
Apartment "1" *-- "2..*" Room : contains
Room "1" *-- "0..*" Sensor : contains
Inhabitant "1" -- "0..*" Threshold : sets
Threshold "1" -- "1" Sensor : for
Threshold "1" -- "1" Inhabitant : set by
Sensor "1" *-- "1..*" MeasuredValue : stores
Sensor "1" *-- "1" MeasuredValue : lastValue
Inhabitant "1" -- "0..*" Sensor : configures (admin)
"E-Monitor" "1" -- "1" SensorController : checks thresholds

TemperatureSensor --|> Sensor
PowerSensor --|> Sensor
@enduml

