City "1" *-- "0..*" Attraction

' An Attraction has multiple GuidedTours
Attraction "1" *-- "0..*" GuidedTour

' A GuidedTour requires one Guide
GuidedTour "1" --> "1" Guide

' A GuidedTour can have up to 20 Visitors
GuidedTour "1" --> "0..20" Visitor

' A Discount is an association between a GuidedTour and a Visitor
GuidedTour "0..*" -- "0..*" Visitor : offers
  [GuidedTour] -- [Discount] -- [Visitor]
  Discount : "amount: double"

@enduml

